class Solution {

    static boolean checktree(int preorder[], int inorder[], int postorder[], int N) {
        return check(preorder, inorder, postorder, 0, N-1, 0, N-1, 0, N-1);
    }

    static boolean check(int pre[], int in[], int post[],
                         int preStart, int preEnd,
                         int inStart, int inEnd,
                         int postStart, int postEnd) {

        if (preStart > preEnd && inStart > inEnd && postStart > postEnd)
            return true;

        if ((preEnd - preStart) != (inEnd - inStart) ||
            (preEnd - preStart) != (postEnd - postStart))
            return false;

        int root = pre[preStart];

        if (root != post[postEnd])
            return false;

        int index = -1;
        for (int i = inStart; i <= inEnd; i++) {
            if (in[i] == root) {
                index = i;
                break;
            }
        }

        if (index == -1)
            return false;

        int leftSize = index - inStart;

        boolean left = check(pre, in, post,
                             preStart + 1, preStart + leftSize,
                             inStart, index - 1,
                             postStart, postStart + leftSize - 1);

        boolean right = check(pre, in, post,
                              preStart + leftSize + 1, preEnd,
                              index + 1, inEnd,
                              postStart + leftSize, postEnd - 1);

        return left && right;
    }
}
